import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {mkdtempSync,writeFileSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {createSourceSessionR679,appendSourceExecutionR679,verifySourceSessionR679} from '../src7/workspaces/canonicalSessionReplayR679.js';
import {R684_SCHEMA,R684_COUNT,R684_SOURCE_BYTES,R684_BOUNDARY,R684_MAX_BUNDLE_BYTES,
 exportPortableSessionBundleR684,parsePortableSessionBundleR684,verifyPortableSessionBundleR684,
 restoreSourceSnapshotR684,serializePortableSessionBundleR684} from '../src7/workspaces/portableSessionBundleR684.js';
const field={count:20736,routeNext:new Uint32Array(20736),C:new Float32Array(20736),
 Phi:new Float32Array(20736),q:new Float32Array(20736),Lambda:new Float32Array(20736),
 scar:new Float32Array(20736),evidence:new Float32Array(20736),continuityGate:new Float32Array(20736)};
for(let i=0;i<20736;i++){
 field.routeNext[i]=i;field.C[i]=.3+.025*(i%12);
 field.Phi[i]=.56;field.q[i]=.12;field.Lambda[i]=.17;field.scar[i]=.08;
 field.evidence[i]=.9;field.continuityGate[i]=.85;
}
for(const [a,b] of [[4,5],[5,6],[6,7],[7,4],[8,5]])field.routeNext[a]=b;
const start=await createSourceSessionR679(field,{createdAt:'2026-10-22T12:00:00.000Z'});
const one=await appendSourceExecutionR679(start,field,{type:'MODE_RUN',address:4,mode:'STABILIZE',depth:10});
const two=await appendSourceExecutionR679(one,field,{type:'OPERATOR_RUN',address:4,channel:'C',operation:'P_rw',iterations:3});
const three=await appendSourceExecutionR679(two,field,{type:'DONOR_REPLAY',effectiveUpdates:59});
assert.equal((await verifySourceSessionR679(three,field)).valid,true);
const sourceBefore={c:Array.from(field.C.slice(0,12)),route:Array.from(field.routeNext.slice(0,12))};
const bundle=await exportPortableSessionBundleR684(three,field,{createdAt:'2026-10-22T13:00:00.000Z'});
assert.equal(bundle.schema,R684_SCHEMA);
assert.equal(bundle.sourceBase64.length,R684_SOURCE_BYTES/3*4);
assert.equal(bundle.sourceCount,R684_COUNT);
assert.equal(bundle.sourceKeys.length,8);
assert.equal(bundle.authority,'LOCAL_ARCHIVED_MODEL_ONLY');
assert.equal(bundle.canonicalMutation,false);
assert.ok(R684_BOUNDARY.includes('NOT an owner signature'));
assert.ok(!('source' in bundle));
const text=serializePortableSessionBundleR684(bundle);
assert.ok(Buffer.byteLength(text)<R684_MAX_BUNDLE_BYTES);
const parsed=parsePortableSessionBundleR684(text);
assert.deepEqual(parsed,bundle,'portable JSON survives exact round trip');
const restored=restoreSourceSnapshotR684(bundle.sourceBase64);
assert.ok(restored.routeNext instanceof Uint32Array);
assert.deepEqual(Array.from(restored.C),Array.from(field.C));
assert.deepEqual(Array.from(restored.routeNext),Array.from(field.routeNext));
const exact=await verifyPortableSessionBundleR684(parsed,field);
assert.equal(exact.valid,true,JSON.stringify(exact.failures));
assert.equal(exact.verifiedEvents,3);
assert.equal(exact.archivedSourceReplayed,true);
assert.equal(exact.sourceMatchesLive,true);
assert.equal(exact.truthClass,'VERIFIED_LOCAL_REPLAY_AND_LIVE_SOURCE_MATCH');
assert.equal(exact.productionVerified,false);
assert.equal(exact.ownerAuthenticated,false);
assert.equal(exact.canonicalMutation,false);
const different={...field,C:field.C.slice()};different.C[4]+=.125;
const historical=await verifyPortableSessionBundleR684(parsed,different);
assert.equal(historical.valid,true,'archived model is reproducible regardless of current source drift');
assert.equal(historical.verifiedEvents,3);
assert.equal(historical.sourceMatchesLive,false);
assert.equal(historical.truthClass,'VERIFIED_ARCHIVED_MODEL_REPLAY_ONLY','never mislabel old model current CanonState');
const unavailable=await verifyPortableSessionBundleR684(parsed);
assert.equal(unavailable.valid,true);
assert.equal(unavailable.sourceMatchesLive,null);
assert.equal(unavailable.truthClass,'VERIFIED_ARCHIVED_MODEL_REPLAY_ONLY');
const tampered=structuredClone(parsed);tampered.session.events[0].action.mode='EXPLORE';
const deny=await verifyPortableSessionBundleR684(tampered);
assert.equal(deny.valid,false);
assert.ok(deny.failures.some(s=>s.includes('PORTABLE_ENVELOPE_DIGEST_MISMATCH')||s.includes('ARCHIVED_REPLAY_')));
const tamperSource=structuredClone(parsed);
const decoded=atob(tamperSource.sourceBase64),altered=decoded.slice(0,100)+'A'+decoded.slice(101);
tamperSource.sourceBase64=btoa(altered);
const sourceDenied=await verifyPortableSessionBundleR684(tamperSource);
assert.equal(sourceDenied.valid,false);
assert.ok(sourceDenied.failures.some(x=>x.includes('ARCHIVED_SOURCE_HASH_MISMATCH')||x.includes('PORTABLE_ENVELOPE_DIGEST_MISMATCH')));
const alteredHash=structuredClone(parsed);alteredHash.sha256='0'.repeat(64);
assert.equal((await verifyPortableSessionBundleR684(alteredHash)).valid,false);
const extra=structuredClone(parsed);extra.sourceKeys[0]='INVENTED';
assert.throws(()=>parsePortableSessionBundleR684(JSON.stringify(extra)),/invalid portable/);
const shortened=structuredClone(parsed);shortened.sourceBase64=shortened.sourceBase64.slice(4);
assert.throws(()=>parsePortableSessionBundleR684(JSON.stringify(shortened)),/wrong length/);
assert.throws(()=>parsePortableSessionBundleR684('x'.repeat(R684_MAX_BUNDLE_BYTES+1)),/size limit/);
const invalid=structuredClone(parsed);invalid.authority='PRODUCTION_VERIFIED';
assert.throws(()=>parsePortableSessionBundleR684(JSON.stringify(invalid)));
await assert.rejects(()=>exportPortableSessionBundleR684(three,different),/refuses unverified session|source drift/);
assert.deepEqual(Array.from(field.C.slice(0,12)),sourceBefore.c,'source immutable');
assert.deepEqual(Array.from(field.routeNext.slice(0,12)),sourceBefore.route,'route immutable');
const root=mkdtempSync(join(tmpdir(),'omega-r684-cli-'));
try{
 const file=join(root,'historical.json');
 writeFileSync(file,text);
 const good=spawnSync(process.execPath,['scripts/verify-portable-session-r684.mjs',file],{cwd:process.cwd(),encoding:'utf8',timeout:60000});
 assert.equal(good.status,0,'offline CLI original source replay failed: '+good.stderr);
 const proof=JSON.parse(good.stdout);
 assert.equal(proof.valid,true);
 assert.equal(proof.verifiedEvents,3);
 assert.equal(proof.offline,true);
 assert.equal(proof.liveSourceAttested,false);
 assert.equal(proof.ownerAuthenticated,false);
 writeFileSync(file,JSON.stringify(tampered));
 const rejected=spawnSync(process.execPath,['scripts/verify-portable-session-r684.mjs',file],{cwd:process.cwd(),encoding:'utf8',timeout:60000});
 assert.equal(rejected.status,1,'offline CLI accepted tampered source evidence');
 const rejection=JSON.parse(rejected.stdout);
 assert.equal(rejection.valid,false);
}finally{rmSync(root,{recursive:true,force:true})}
console.log('R684 PASS: source-complete 663552-byte export, actual 3-mode/donor replay, import, cryptographic integrity, historical source drift, tamper refusal and no CanonState promotion');
